class Solution {
public:
    long long minTime(vector<int>& forward, vector<int>& backward, vector<int>& queries) {
        int n = forward.size();
        vector<long long> F(n + 1, 0), G(n + 1, 0);
        for (int i = 0; i < n; i++) { F[i + 1] = F[i] + forward[i]; G[i + 1] = G[i] + backward[i]; }
        long long tf = F[n], tb = G[n], ans = 0; int cur = 0;
        auto cw = [&](int u, int v) { return ((F[v] - F[u]) % tf + tf) % tf; };
        auto ccw = [&](int u, int v) { return ((G[u + 1] - G[v + 1]) % tb + tb) % tb; };
        for (int q : queries) { ans += min(cw(cur, q), ccw(cur, q)); cur = q; }
        return ans;
    }
};

