class Solution {
    public long minTime(int[] forward, int[] backward, int[] queries) {
        int n = forward.length;
        long[] F = new long[n + 1], G = new long[n + 1];
        for (int i = 0; i < n; i++) { F[i + 1] = F[i] + forward[i]; G[i + 1] = G[i] + backward[i]; }
        long tf = F[n], tb = G[n], ans = 0; int cur = 0;
        for (int q : queries) {
            long a = ((F[q] - F[cur]) % tf + tf) % tf;
            long b = ((G[cur + 1] - G[q + 1]) % tb + tb) % tb;
            ans += Math.min(a, b);
            cur = q;
        }
        return ans;
    }
}

