class Solution:
    def minTime(self, forward: List[int], backward: List[int], queries: List[int]) -> int:
        n = len(forward)
        def dist(u, v):
            a, i = 0, u
            while i != v: a += forward[i]; i = (i + 1) % n
            b, i = 0, u
            while i != v: b += backward[i]; i = (i - 1) % n
            return min(a, b)
        ans, cur = 0, 0
        for q in queries:
            ans += dist(cur, q)
            cur = q
        return ans

